// Generates hooks/scripts/lib/flow-parse.gen.mjs from the server's flow parser,
// so the hook-side lint uses the exact parser the dashboard uses. Hooks run on
// plain Node (no TypeScript), hence the type-stripped copy.
//
// Usage: node scripts/gen-flow-parser.mjs [--check]
//   --check  exit 1 when the generated file is out of date (no write)
// Needs Node >= 22.13 (module.stripTypeScriptTypes); the output runs on any Node 18+.

import { readFileSync, writeFileSync } from 'node:fs'
import { resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import * as nodeModule from 'node:module'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const SRC = 'app/server/src/flow/parse.ts'
const OUT = 'hooks/scripts/lib/flow-parse.gen.mjs'

/** False on Node < 22.13, where the generator cannot run (the generated file still works). */
export const canGenerate = typeof nodeModule.stripTypeScriptTypes === 'function'

export function generate() {
  const ts = readFileSync(resolve(root, SRC), 'utf8').replace(/\r\n/g, '\n')
  // 'transform' re-prints the code (comments are lost); 'strip' would leave the
  // erased types as runs of spaces.
  const js = nodeModule.stripTypeScriptTypes(ts, { mode: 'transform' })
  return `// GENERATED by scripts/gen-flow-parser.mjs from ${SRC} — do not edit.\n\n${js.trim()}\n`
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const next = generate()
  const outPath = resolve(root, OUT)
  let current = ''
  try {
    current = readFileSync(outPath, 'utf8').replace(/\r\n/g, '\n')
  } catch {}
  if (process.argv.includes('--check')) {
    if (current !== next) {
      console.error(`${OUT} is out of date — run: node scripts/gen-flow-parser.mjs`)
      process.exit(1)
    }
    console.log(`${OUT} is up to date`)
  } else {
    writeFileSync(outPath, next)
    console.log(`wrote ${OUT}`)
  }
}
